import{_ as l,c as a,aU as e,a as t}from"./chunks/framework.DP-R0N-M.js";const c=JSON.parse('{"title":"01-中国近代史概述","description":"","frontmatter":{},"headers":[],"relativePath":"note/history/modern-chinese-history/中国近代史概述.md","filePath":"note/history/modern-chinese-history/中国近代史概述.md","lastUpdated":1763295562000}'),r={name:"note/history/modern-chinese-history/中国近代史概述.md"};function o(h,i,p,n,d,s){return t(),a("div",null,[...i[0]||(i[0]=[e('<h1 id="_01-中国近代史概述" tabindex="-1">01-中国近代史概述 <a class="header-anchor" href="#_01-中国近代史概述" aria-label="Permalink to &quot;01-中国近代史概述&quot;">​</a></h1><p>勿忘历史 吾辈当自强 我们没有资格替先辈们原谅 忘记历史等同于背叛 铭记才能开创未来。</p><h2 id="前期军阀" tabindex="-1">前期军阀 <a class="header-anchor" href="#前期军阀" aria-label="Permalink to &quot;前期军阀&quot;">​</a></h2><p>东北 张学良 <br> 西北王 冯玉祥<br> 山东 韩复榘<br> 广西 李宗仁，白崇禧<br> 云南 龙云<br> 山西 阎锡山<br> 宁夏，青海 马家帮 马步芳 马鸿逵 马鸿宾<br></p><h2 id="时间线" tabindex="-1">时间线 <a class="header-anchor" href="#时间线" aria-label="Permalink to &quot;时间线&quot;">​</a></h2><ul><li>1949-10-01 中华人民共和国成立</li><li>1950年6月25日 - 1953年7月27日 朝鲜战争。</li><li>1951年10月26日 ‌西藏和平解放</li><li>1952年底 土地改革基本完成</li><li>1953-1957年 第一个五年计划</li><li>1954年，第一届全国人民代表大会召开，制定《中华人民共和国宪法》</li><li>1955年，周恩来出席万隆会议。</li><li>1956年，三大改造基本完成。</li><li>1958年，开始“大跃进”和人民公社化运动。‌大跃进运动开始于1958年，结束于1961年</li><li>1958-1962年，‌第二个五年计划。</li><li>1958年8月至10月，炮击金门。</li><li>1958年7月，赫鲁晓夫打着中苏合作的旗号说要在中国建长波电台，遭到毛主席的当场拒绝。</li><li>1959年至1961年，三年自然灾害。</li><li>1960年2月-1969年7月，被誉为世界八大奇迹的红旗渠竣工。</li><li>1960年11月5日，中国自行制造的第一枚导弹东风一号，发射成功！东风导弹诞生！</li><li>1962年10月20日至11月21日，‌对印自卫反击战</li><li>1961年至1974年，援老抗美防空作战</li><li>1964年，我国第一颗原子弹爆炸成功</li><li>1965年至1973年间，抗美援越。</li><li>1966年10月27日 上午9时，东风二号导弹托举着核弹头直冲云霄，在罗布泊试射成功，也标识着我国首枚导弹核武器发射试验成功!</li><li>1966-1976年，“文化大革命”</li><li>1966-1970年，‌第三个五年计划</li><li>1967年6月17日，中国第一颗氢弹于1967年6月17日在新疆罗布泊爆炸成功‌。‌</li><li>1969年3月2日至4月2日 ‌珍宝岛战役，</li><li>1969年8月，苏联准备对中国展开核打击，教员提出<strong>史上最强阳谋</strong>，<strong>换家战术</strong>，轻松化解此次危机。</li><li>1970年4月24日，中国第一颗人造卫星发射成功</li><li>1971年，中国恢复在联合国的合法席位</li><li>1971年，毛主席通过“乒乓外交”，以“小球转动大球”的方式，促成了尼克松1972年访华，催生了《中美联合公报》，为两国建交打下了基础。</li><li>1971年9月13日，林彪携家属坐飞机逃跑，结果在蒙古温都尔汗坠机，导致机毁人亡。</li><li>1972年，尼克松访华，中美关系开始正常化；日本首相田中角荣访华。</li><li>1974年1月19日 至 1974年1月20日，中越西沙海战。</li><li>1975年4月5日，蒋介石去世。</li><li>1976年9月9日零时10分，伟大的毛主席病逝。</li><li>1976年10月6日，粉碎“四人帮”</li><li>1978年12月，实行”改革开放“</li><li>1979年1月1日，中美两国正式建交</li><li>1979年到1989年，‌对越战争</li><li>1988年，越南南沙海战</li><li>1994年12月14日-2006年5月20日，世界上最大的水利工程之一的‌三峡大坝竣工完成。</li></ul><h2 id="石器时代" tabindex="-1">&quot;石器时代&quot; <a class="header-anchor" href="#石器时代" aria-label="Permalink to &quot;&quot;石器时代&quot;&quot;">​</a></h2><ol><li>1966年1月28日，导弹核武器试验成功。</li><li>1966年3月17日，江苏无锡试制成功医学上使用的放射性同位素扫描机。</li><li>1966年3月4日，贵昆铁路比原计划提前9个月接轨。</li><li>1966年5月3日，第一批&quot;红旗&quot;高级轿车出厂。</li><li>1966年5月9日，进行了一次含有热核材料的核试验。</li><li>1966年10月8日，制成第一批10万千瓦水轮发电机组。</li><li>1966年10月27日，第一颗装有核弹头的地地导弹飞行爆炸成功。</li><li>1966年12月23日，在世界上第一次人工合成结晶胰岛素。</li><li>1966年12月28日，成功进行一次新的核爆炸。</li><li>1967年6月17日，第一颗氢弹爆炸成功。</li><li>1967年8月5日，观测地震的强震仪在北京试制成功并投入使用。</li><li>1967年10月6日，新型晶体管大型通用数字计算机在北京研究试制成功。</li><li>1968年12月27日，成功爆炸一颗氢弹。</li><li>1969年5月5日，上海试制成功抗菌素&quot;庆大霉素&quot;</li><li>1969年9月23日，成功进行首次地下核试验。</li><li>1969年9月29日，进行一次新的氢弹爆炸。</li><li>1970年3月29日，第一台高分子材料万能试验机在长春制造成功。</li><li>1970年4月24日，第一颗人造地球卫星&quot;东方红一号&quot;发射成功。</li><li>1970年7月1日，成昆铁路建成通车。</li><li>1971年1月8日，第一艘万吨巨轮&quot;东风&quot;号建成。</li><li>1971年3月3日，发射一颗科学试验卫星。</li><li>1971年7月18日，针刺麻醉成功。</li><li>1971年11月18日，进行一次新的核试验。</li><li>1971年12月25日，葛洲坝一期工程开工。</li><li>1972年4月2日，第一艘万吨油轮&quot;大庆27号&quot;下水。</li><li>1972年6月28日，成功进行一次氢弹试验。</li><li>1972年8月27日，第一台百万次集成电路电子计算机研制成功。28.1972年9月3日，第一台天文测时、测纬光电等高仪研制成功。</li><li>1973年6月27日，进行一次新的氢弹试验。</li><li>1973年8月26日，第一台每秒钟运算百万次的集成电路通用数字电子计算机在北京试制成功。</li><li>1973年9月15日，黄河青铜峡水利枢纽建成。</li><li>1973年10月3日，最大竖井钻井研制成功。</li><li>1973年，籼型杂交水稻培育成功。</li><li>1974年4月30日，第一台医用电子感应加速器试制成功。</li><li>1974年6月17日，进行一次新的核试验。</li><li>1974年10月16日，新疆哈密矿务局露天煤矿投产。</li><li>1975年1月5日，研制成功对太阳进行高分辨率观测的射电望远镜。</li><li>1975年2月3日，研制成功一台受控热核反应实验装置。</li><li>1975年3月8日，第一台相立式精密激光测距仪研制成功。</li><li>1975年4月8日，第一台混合模拟电子计算机在北京试制成功。</li><li>1975年7月26日，第三次成功发射人造地球卫星。</li><li>1975年9月26日，大型精密科学仪器扫描电子显微镜在北京试制成功。</li><li>1975年10月27日，进行一次地下核试验。</li><li>1975年11月26日，第四次发射人造地球卫星，运行三天后按计划返回地面。</li><li>1976年1月23日，进行一次新的核试验。</li><li>1976年7月6日，滇藏公路建成通车。</li><li>1976年8月30日，第六次发射一颗人造卫星。</li><li>1976年9月26日，进行一次新的核试验。</li><li>1976年10月17日，成功进行一次地下核试验。</li><li>1976年11月17日，进行一次新的氢弹试验。</li><li>1976年12月7日，第七次发射人造地球卫星，10日公布卫星已按计划准确返回地面。</li></ol><h2 id="第一次访问苏联" tabindex="-1">第一次访问苏联 <a class="header-anchor" href="#第一次访问苏联" aria-label="Permalink to &quot;第一次访问苏联&quot;">​</a></h2><p>1949年12月，毛泽东开始了他的第一次莫斯科之行，这是他一生当中第一次出国访问。毛泽东此次出访，一是给斯大林祝寿，二是签订新的中苏条约。</p><h2 id="‌三年自然灾害" tabindex="-1">‌三年自然灾害 <a class="header-anchor" href="#‌三年自然灾害" aria-label="Permalink to &quot;‌三年自然灾害&quot;">​</a></h2><p>‌三年自然灾害指的是1959年至1961年‌。这一时期被称为“三年困难时期”或“三年经济困难”，主要是由于“大跃进”和人民公社化运动中的严重“左”倾错误，加上从1959年到1961年，中国农田连续几年遭受大面积自然灾害，导致全国性的粮食和副食品短缺危机。‌ 在这三年中，中国遭受了严重的旱灾和其他自然灾害，影响了农业生产和粮食供应。1959年，全国大部分地区遭受严重春旱，许多地区的小河和水库干涸，农作物生长受到严重影响。1960年，旱情进一步扩大，北方地区尤为严重。这些自然灾害加剧了经济困难，导致大量人口饥饿和死亡。</p><p>在这三年中，中国遭受了严重的旱灾和其他自然灾害，影响了农业生产和粮食供应。1959年，全国大部分地区遭受严重春旱，许多地区的小河和水库干涸，农作物生长受到严重影响。1960年，旱情进一步扩大，北方地区尤为严重。这些自然灾害加剧了经济困难，导致大量人口饥饿和死亡。</p><h2 id="文化大革命" tabindex="-1">文化大革命 <a class="header-anchor" href="#文化大革命" aria-label="Permalink to &quot;文化大革命&quot;">​</a></h2><p>‌文化大革命开始于1966年5月，结束于1976年10月‌。文化大革命全称“无产阶级文化大革命”，是一场由领导者错误发动，被反革命集团利用，给党、国家和各族人民带来严重灾难的内乱。</p><h2 id="原子弹-导弹" tabindex="-1">原子弹&amp;导弹 <a class="header-anchor" href="#原子弹-导弹" aria-label="Permalink to &quot;原子弹&amp;导弹&quot;">​</a></h2><p>1966年10月27日 上午9时，我国首枚导弹核武器发射试验成功。发射任务结束后的第二天，也就是1966年10月28日，东风基地举行了隆重的庆祝大会。聂荣臻元帅激动地说：“我国进行的导弹核武器试验圆满成功了!” 从第一次核爆炸到发射核弹头 美国用了13年 前苏联用了6年 中国只用了2年 !</p><p>1960年11月5日 东风一号中程导弹试射成功</p><p>1964年6月29日 东风二号中程导弹试射成功</p><p>1966年12月26日 东风三号中程导弹试射成功</p><p>1970年1月30日 东风四号中远程导弹试射成功</p><p>1971年9月10日 东风五号洲际导弹试射</p><p>1980年5月18日 我国第一枚洲际导弹全程试验成功</p><h2 id="五年计划" tabindex="-1">五年计划 <a class="header-anchor" href="#五年计划" aria-label="Permalink to &quot;五年计划&quot;">​</a></h2><p>苏联帮助中国建设的156个项目是中国第一个五年计划时期从苏联与东欧国家引进的156项重点工矿业基本建设项目‌。这些项目起始于20世纪五十年代初，持续约十年，直至中苏关系破裂为止。这些项目奠定了中国初步工业化的部门经济基础，涉及钢铁、煤炭、冶炼、发电、造船、航空、建材、机械电子、化工、纺织、通讯、工具、交通运输、兵器等多个部门，基本包括了一个国家全部的重工业部门。‌</p><h2 id="斯大林" tabindex="-1">斯大林 <a class="header-anchor" href="#斯大林" aria-label="Permalink to &quot;斯大林&quot;">​</a></h2><p>1953年3月5日晚上，斯大林逝世。</p><h2 id="赫鲁晓夫" tabindex="-1">赫鲁晓夫 <a class="header-anchor" href="#赫鲁晓夫" aria-label="Permalink to &quot;赫鲁晓夫&quot;">​</a></h2><p>‌尼基塔·谢尔盖耶维奇·赫鲁晓夫上台时间为1953年9月3日‌。赫鲁晓夫在1953年9月3日当选为苏联共产党中央委员会第一书记，随后在1956年2月的苏共二十大上发表了著名的“秘密报告”，对前领导人约瑟夫·斯大林展开全面批评，引发了东欧的一系列骚乱。‌</p><p>赫鲁晓夫上台后，实施了一系列改革措施。他推行去斯大林化政策，为大清洗中的受害者平反，加强社会主义民主和法制建设。在经济方面，他进行了农业改革，改善了苏联的民生经济。然而，他的改革并没有从根本上解决苏联经济体制的问题，导致经济体制进一步僵化。1964年10月，赫鲁晓夫在黑海之滨度假时被解除党内外一切职务，从此被迫淡出政坛。</p><p>1958年，赫鲁晓夫打着中苏合作的旗号说要在中国建长波电台，遭到毛主席的强烈反对。 赫鲁晓夫特别生气，认为中国居然敢不给他面子，非得教训一下这个“小弟”。就这样，从这一年起，苏联陆续撤回了给中国的所有援助，包括之前的专家和156个项目的所有资料。 其中还包括核反应堆相关的项目，那时候赫鲁晓夫居然张狂地讲：“没苏联帮忙，中国就算 20 年也搞不出原子弹。”</p><p>1964 年，中国成功造出了第一颗原子弹，这把苏联惊得不行，因为之前苏联压根没想到，中国没靠外界帮忙，居然能造出原子弹，还在这么短的时间里。</p><h2 id="换家战术" tabindex="-1">换家战术 <a class="header-anchor" href="#换家战术" aria-label="Permalink to &quot;换家战术&quot;">​</a></h2><p>勃列日涅夫上台后，中国和苏联的关系变得更糟了，接着就引发了中苏珍宝岛冲突。</p><p>珍宝岛冲突，一方面是苏联跟中国关系变得极度糟糕的一个标志，另一方面也是苏联打算对中国实施核打击的导火线。</p><p>珍宝岛的每次小冲突都是以苏军失败结尾，这消息传到莫斯科，勃列日涅夫马上就火冒三丈，以苏联军方为头的“鹰派”势力使劲主张得对中国采取行动，这所谓的行动就是对中国搞核打击。</p><p>军方的提议肯定是获得了勃列日涅夫的赞同，所以苏联在短短几个月里到处调动兵力，在远东地区增兵达百万之多，还把百万规模级别的核导弹瞄向了中国，准备对中国实施核打击。</p><p>不过在真正开始行动前，苏联为了谨慎起见，还是提前跟美国打了招呼。</p><p>1969 年 8 月 20 号，勃列日涅夫给苏联驻美大使发了份秘密电报。这电报里说的大概意思是：苏联很快要对中国搞“外科手术式”的核打击，让大使去问问美国总统尼克松的想法，重点是盼着美方能保持中立，别插手苏联对中国的行动。</p><p>尼克松觉得，得想办法把这消息告知中国。可一个实实在在的问题横在了他跟前，那就是美国跟中国根本就没有外交关系，这时候美国要怎么把这个消息传给中国呢？</p><p>并且中美两国长久以来一直是敌对的，就算能把消息传出去，中国那边也不一定信，更关键的是，要是被美国国内的反对党抓住了小辫子，那可就成了惊天的政治丑闻了，当总统的尼克松肯定会被安上“通共”的名号，名声扫地。</p><p>琢磨了好久，尼克松琢磨出一个不错的主意，就是把这消息登在一份不怎么起眼的小报上，这样的话，既不会太招人注意，让反对派抓到啥漏洞，还能给中国提个醒。 就在这一年 8 月 28 日，美国的《华盛顿明星报》冷不丁刊登了一篇文章，文中表示，苏联打算对邻国中国开展“外科手术式”的核打击。听到这则消息，毛主席特别镇定，不紧不慢地点了一根烟，跟身边的人讲：“他要是敢扔，咱中国的 8 亿军民就敢回击！”</p><h2 id="中越战争" tabindex="-1">中越战争 <a class="header-anchor" href="#中越战争" aria-label="Permalink to &quot;中越战争&quot;">​</a></h2><h3 id="抗美援越" tabindex="-1">抗美援越 <a class="header-anchor" href="#抗美援越" aria-label="Permalink to &quot;抗美援越&quot;">​</a></h3><p>1965-1973年中国对越南人民抗美救国战争提供的军事援助 1964年8月5日，美国借“北部湾事件”，对越南发动侵略战争，同时其军用飞机侵入中国海南岛地区和云南、广西上空，投掷炸弹和发射导弹，打死打伤中国船员和解放军战士，威胁中国安全。 1965年4月，越南劳动党请求中国支援。毛泽东主席决定向越南提供全面无私的援助。1973年1月27日，越共、越南南方民族解放阵线、美国、南越阮文绍政权四方在巴黎签署了《关于在越南结束战争、恢复和平的协定》。3月，侵越美军部队开始撤出越南南方。1973年8月，在越执行援越抗美任务的中国支援部队全部撤回国内。</p><h3 id="中越西沙海战" tabindex="-1">中越西沙海战 <a class="header-anchor" href="#中越西沙海战" aria-label="Permalink to &quot;中越西沙海战&quot;">​</a></h3><p>1974年1月19日 至 1974年1月20日，西沙群岛自卫反击战。</p><h3 id="南沙海战" tabindex="-1">南沙海战 <a class="header-anchor" href="#南沙海战" aria-label="Permalink to &quot;南沙海战&quot;">​</a></h3><p>越南除了觊觎我国的西沙群岛之外，还觊觎我国的南沙群岛，想将南沙群岛的岛礁并入自己的版图。</p><p>1988年，为了保住我国的南沙群岛，我国和越南爆发南沙海战，最终击败越南，收复了南沙群岛。</p>',50)])])}const q=l(r,[["render",o]]);export{c as __pageData,q as default};
